INSERT INTO email_templates VALUES(1,'Quotation Email','quotation','Your Solar System Quotation - {quotation_number}','<p>Dear {customer_name},</p><p>Please find attached your quotation <strong>{quotation_number}</strong> for a solar system installation.</p><p><strong>Total Amount: ₹{total_amount}</strong></p><p>This quotation is valid until {valid_until}.</p><p>Please feel free to contact us for any queries.</p><p>Best regards,<br>Palawat Solar Team</p>',NULL,1,'2026-03-19 08:37:13','2026-03-19 08:37:13');
INSERT INTO email_templates VALUES(2,'Follow Up Email','follow_up','Following up on your Solar Inquiry','<p>Dear {customer_name},</p><p>We wanted to follow up on your recent inquiry about solar panel installation.</p><p>Our team is ready to provide you with a customized solution.</p><p>Best regards,<br>Palawat Solar</p>',NULL,1,'2026-03-19 08:37:13','2026-03-19 08:37:13');
INSERT INTO email_templates VALUES(3,'Welcome Email','welcome','Welcome to SolarTech Family!','<p>Dear {customer_name},</p><p>Welcome to Palawat Solar! We are thrilled to have you as our customer.</p><p>Your order <strong>{order_number}</strong> has been confirmed.</p><p>Best regards,<br>Palawat Solar Team</p>',NULL,1,'2026-03-19 08:37:13','2026-03-19 08:37:13');
INSERT INTO print_formats VALUES(1,'Default Quotation','quotation',NULL,NULL,unistr('<!DOCTYPE html>\u000a<html lang="en">\u000a<head>\u000a    <meta charset="UTF-8">\u000a    <title>Quotation — {{ $quotation->quotation_number }}</title>\u000a    <style>\u000a        * { margin: 0; padding: 0; box-sizing: border-box; }\u000a        body { font-family: ''Segoe UI'', Arial, sans-serif; font-size: 13px; color: #1a1a2e; background: #fff; }\u000a        .page { max-width: 820px; margin: 0 auto; padding: 40px; }\u000a\u000a        .doc-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 36px; padding-bottom: 24px; border-bottom: 3px solid #f97316; }\u000a        .company-name { font-size: 22px; font-weight: 800; color: #1a1a2e; }\u000a        .company-tagline { font-size: 11px; color: #6b7280; margin-top: 2px; }\u000a        .company-meta { margin-top: 10px; font-size: 11px; color: #6b7280; line-height: 1.7; }\u000a        .doc-badge { text-align: right; }\u000a        .doc-type { font-size: 28px; font-weight: 900; color: #f97316; letter-spacing: -1px; text-transform: uppercase; }\u000a        .doc-number { font-size: 13px; font-weight: 600; color: #374151; margin-top: 4px; }\u000a        .doc-date { font-size: 11px; color: #9ca3af; margin-top: 2px; }\u000a        .validity { font-size: 11px; margin-top: 4px; }\u000a        .validity.expired { color: #dc2626; font-weight: 600; }\u000a        .validity.valid   { color: #16a34a; font-weight: 600; }\u000a\u000a        .status-pill { display: inline-flex; align-items: center; padding: 3px 10px; border-radius: 20px; font-size: 10px; font-weight: 700; text-transform: uppercase; margin-top: 6px; }\u000a        .s-pending  { background: #fef9c3; color: #a16207; }\u000a        .s-sent     { background: #dbeafe; color: #1d4ed8; }\u000a        .s-approved { background: #dcfce7; color: #15803d; }\u000a        .s-rejected { background: #fee2e2; color: #dc2626; }\u000a        .s-expired  { background: #f3f4f6; color: #6b7280; }\u000a\u000a        .parties { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 32px; }\u000a        .party-card { background: #f9fafb; border-radius: 10px; padding: 16px 18px; }\u000a        .party-label { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #9ca3af; margin-bottom: 8px; }\u000a        .party-name { font-size: 14px; font-weight: 700; color: #111827; margin-bottom: 4px; }\u000a        .party-detail { font-size: 11px; color: #6b7280; line-height: 1.7; }\u000a\u000a        .section-title { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #9ca3af; margin-bottom: 10px; }\u000a        table { width: 100%; border-collapse: collapse; margin-bottom: 24px; }\u000a        thead tr { background: #1a1a2e; color: #fff; }\u000a        thead th { padding: 10px 14px; text-align: left; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; }\u000a        thead th.right { text-align: right; }\u000a        thead th.center { text-align: center; }\u000a        tbody tr { border-bottom: 1px solid #f3f4f6; }\u000a        tbody tr:nth-child(even) { background: #f9fafb; }\u000a        tbody td { padding: 10px 14px; font-size: 12px; color: #374151; }\u000a        tbody td.center { text-align: center; }\u000a        tbody td.right { text-align: right; font-weight: 600; }\u000a\u000a        .totals-wrap { display: flex; justify-content: flex-end; margin-bottom: 32px; }\u000a        .totals-box { width: 280px; }\u000a        .totals-row { display: flex; justify-content: space-between; padding: 6px 0; font-size: 12px; border-bottom: 1px solid #f3f4f6; color: #6b7280; }\u000a        .totals-row.grand { font-size: 15px; font-weight: 800; color: #1a1a2e; border-bottom: none; border-top: 2px solid #1a1a2e; padding-top: 10px; margin-top: 4px; }\u000a        .totals-row.grand span:last-child { color: #f97316; }\u000a        .totals-row.discount span:last-child { color: #16a34a; }\u000a\u000a        .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 32px; }\u000a        .info-box { background: #f9fafb; border-radius: 10px; padding: 16px 18px; }\u000a        .info-box-title { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #9ca3af; margin-bottom: 8px; }\u000a        .info-box p { font-size: 12px; color: #374151; line-height: 1.6; }\u000a        .bank-row { font-size: 11px; color: #6b7280; margin-bottom: 3px; }\u000a        .bank-row strong { color: #374151; }\u000a\u000a        .terms-box { background: #fff7ed; border: 1px solid #fed7aa; border-radius: 10px; padding: 16px 18px; margin-bottom: 32px; }\u000a        .terms-box-title { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #c2410c; margin-bottom: 8px; }\u000a        .terms-box p { font-size: 11px; color: #7c2d12; line-height: 1.7; white-space: pre-line; }\u000a\u000a        .doc-footer { text-align: center; border-top: 1px solid #f3f4f6; padding-top: 16px; font-size: 10px; color: #9ca3af; line-height: 1.8; }\u000a        .accent { color: #f97316; font-weight: 700; }\u000a\u000a        @media print {\u000a            body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\u000a            .page { padding: 20px; }\u000a        }\u000a    </style>\u000a</head>\u000a<body>\u000a<div class="page">\u000a\u000a    <div class="doc-header">\u000a        <div>\u000a            <div class="company-name">{{ $settings[''company_name''] ?? ''SolarTech ERP'' }}</div>\u000a            @if(!empty($settings[''company_tagline'']))<div class="company-tagline">{{ $settings[''company_tagline''] }}</div>@endif\u000a            <div class="company-meta">\u000a                @if(!empty($settings[''company_email''])){{ $settings[''company_email''] }}<br>@endif\u000a                @if(!empty($settings[''company_phone''])){{ $settings[''company_phone''] }}<br>@endif\u000a                @if(!empty($settings[''company_address''])){{ $settings[''company_address''] }}<br>@endif\u000a                @if(!empty($settings[''gst_number'']))<strong>GST:</strong> {{ $settings[''gst_number''] }}@endif\u000a            </div>\u000a        </div>\u000a        <div class="doc-badge">\u000a            <div class="doc-type">Quotation</div>\u000a            <div class="doc-number">{{ $quotation->quotation_number }}</div>\u000a            <div class="doc-date">Date: {{ $quotation->created_at->format(''d M Y'') }}</div>\u000a            @if($quotation->valid_until)\u000a            <div class="validity {{ $quotation->valid_until->isPast() ? ''expired'' : ''valid'' }}">\u000a                Valid Until: {{ $quotation->valid_until->format(''d M Y'') }}\u000a            </div>\u000a            @endif\u000a            <span class="status-pill s-{{ $quotation->status }}">{{ ucfirst($quotation->status) }}</span>\u000a        </div>\u000a    </div>\u000a\u000a    <div class="parties">\u000a        <div class="party-card">\u000a            <div class="party-label">Quotation For</div>\u000a            <div class="party-name">{{ $quotation->customer_name }}</div>\u000a            <div class="party-detail">\u000a                {{ $quotation->customer_email }}<br>\u000a                {{ $quotation->customer_phone }}<br>\u000a                {{ $quotation->customer_address }}\u000a            </div>\u000a        </div>\u000a        <div class="party-card">\u000a            <div class="party-label">Issued By</div>\u000a            <div class="party-name">{{ $settings[''company_name''] ?? ''SolarTech ERP'' }}</div>\u000a            <div class="party-detail">\u000a                @if(!empty($settings[''company_email''])){{ $settings[''company_email''] }}<br>@endif\u000a                @if(!empty($settings[''company_phone''])){{ $settings[''company_phone''] }}<br>@endif\u000a                @if(!empty($settings[''gst_number'']))GST: {{ $settings[''gst_number''] }}<br>@endif\u000a                @if(!empty($settings[''pan_number'']))PAN: {{ $settings[''pan_number''] }}@endif\u000a            </div>\u000a        </div>\u000a    </div>\u000a\u000a    <div class="section-title">Quoted Items</div>\u000a    <table>\u000a        <thead>\u000a            <tr>\u000a                <th style="width:40px;">#</th>\u000a                <th>Description</th>\u000a                <th class="center" style="width:70px;">Qty</th>\u000a                <th class="right" style="width:120px;">Unit Price</th>\u000a                <th class="right" style="width:120px;">Total</th>\u000a            </tr>\u000a        </thead>\u000a        <tbody>\u000a            @foreach($quotation->items as $i => $item)\u000a            <tr>\u000a                <td>{{ $i + 1 }}</td>\u000a                <td>{{ $item->description }}</td>\u000a                <td class="center">{{ $item->quantity }}</td>\u000a                <td class="right">₹{{ number_format($item->unit_price, 2) }}</td>\u000a                <td class="right">₹{{ number_format($item->total_price, 2) }}</td>\u000a            </tr>\u000a            @endforeach\u000a        </tbody>\u000a    </table>\u000a\u000a    <div class="totals-wrap">\u000a        <div class="totals-box">\u000a            <div class="totals-row"><span>Subtotal</span><span>₹{{ number_format($quotation->total_amount, 2) }}</span></div>\u000a            @if($quotation->tax_amount > 0)\u000a            <div class="totals-row"><span>Tax</span><span>+₹{{ number_format($quotation->tax_amount, 2) }}</span></div>\u000a            @endif\u000a            @if($quotation->discount_amount > 0)\u000a            <div class="totals-row discount"><span>Discount</span><span>-₹{{ number_format($quotation->discount_amount, 2) }}</span></div>\u000a            @endif\u000a            <div class="totals-row grand"><span>Grand Total</span><span>₹{{ number_format($quotation->final_amount, 2) }}</span></div>\u000a        </div>\u000a    </div>\u000a\u000a    <div class="info-grid">\u000a        @if($quotation->notes)\u000a        <div class="info-box">\u000a            <div class="info-box-title">Notes</div>\u000a            <p>{{ $quotation->notes }}</p>\u000a        </div>\u000a        @endif\u000a        @if(!empty($settings[''bank_name'']))\u000a        <div class="info-box">\u000a            <div class="info-box-title">Bank Details</div>\u000a            <div class="bank-row"><strong>Bank:</strong> {{ $settings[''bank_name''] }}</div>\u000a            <div class="bank-row"><strong>A/C Name:</strong> {{ $settings[''bank_account_name''] ?? '''' }}</div>\u000a            <div class="bank-row"><strong>A/C No:</strong> {{ $settings[''bank_account_number''] ?? '''' }}</div>\u000a            <div class="bank-row"><strong>IFSC:</strong> {{ $settings[''bank_ifsc''] ?? '''' }}</div>\u000a            @if(!empty($settings[''upi_id'']))<div class="bank-row"><strong>UPI:</strong> {{ $settings[''upi_id''] }}</div>@endif\u000a        </div>\u000a        @endif\u000a    </div>\u000a\u000a    @if(!empty($settings[''quotation_terms'']))\u000a    <div class="terms-box">\u000a        <div class="terms-box-title">Terms & Conditions</div>\u000a        <p>{{ $settings[''quotation_terms''] }}</p>\u000a    </div>\u000a    @endif\u000a\u000a    <div class="doc-footer">\u000a        @if(!empty($settings[''invoice_footer''])){{ $settings[''invoice_footer''] }}<br>@else\u000a        This quotation is valid for the period mentioned above. Prices are subject to change thereafter.<br>@endif\u000a        <span class="accent">{{ $settings[''company_name''] ?? ''SolarTech ERP'' }}</span>\u000a        @if(!empty($settings[''company_website''])) · {{ $settings[''company_website''] }}@endif\u000a    </div>\u000a\u000a</div>\u000a</body>\u000a</html>\u000a'),0,1,'A4','portrait','2026-03-19 10:41:28','2026-03-20 03:56:33');
INSERT INTO print_formats VALUES(2,'Default Sales Order','sales_order',NULL,NULL,unistr('<!DOCTYPE html>\u000a<html lang="en">\u000a<head>\u000a    <meta charset="UTF-8">\u000a    <meta name="viewport" content="width=device-width, initial-scale=1.0">\u000a    <title>Sales Order — {{ $order->order_number }}</title>\u000a    <style>\u000a        * { margin: 0; padding: 0; box-sizing: border-box; }\u000a        body { font-family: ''Segoe UI'', Arial, sans-serif; font-size: 13px; color: #1a1a2e; background: #fff; }\u000a\u000a        .page { max-width: 820px; margin: 0 auto; padding: 40px; }\u000a\u000a        /* Header */\u000a        .doc-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 36px; padding-bottom: 24px; border-bottom: 3px solid #f97316; }\u000a        .company-brand .company-name { font-size: 22px; font-weight: 800; color: #1a1a2e; letter-spacing: -0.5px; }\u000a        .company-brand .company-tagline { font-size: 11px; color: #6b7280; margin-top: 2px; }\u000a        .company-brand .company-meta { margin-top: 10px; font-size: 11px; color: #6b7280; line-height: 1.7; }\u000a        .doc-badge { text-align: right; }\u000a        .doc-badge .doc-type { font-size: 28px; font-weight: 900; color: #f97316; letter-spacing: -1px; text-transform: uppercase; }\u000a        .doc-badge .doc-number { font-size: 13px; font-weight: 600; color: #374151; margin-top: 4px; }\u000a        .doc-badge .doc-date { font-size: 11px; color: #9ca3af; margin-top: 2px; }\u000a\u000a        /* Status Banner */\u000a        .status-banner { display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px; border-radius: 20px; font-size: 11px; font-weight: 600; margin-top: 6px; text-transform: uppercase; letter-spacing: 0.5px; }\u000a        .status-confirmed  { background: #dbeafe; color: #1d4ed8; }\u000a        .status-processing { background: #fef9c3; color: #a16207; }\u000a        .status-dispatched { background: #ede9fe; color: #7c3aed; }\u000a        .status-completed  { background: #dcfce7; color: #15803d; }\u000a        .status-cancelled  { background: #fee2e2; color: #dc2626; }\u000a        .pay-pending  { background: #fef9c3; color: #a16207; }\u000a        .pay-partial  { background: #dbeafe; color: #1d4ed8; }\u000a        .pay-paid     { background: #dcfce7; color: #15803d; }\u000a\u000a        /* Parties */\u000a        .parties { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 32px; }\u000a        .party-card { background: #f9fafb; border-radius: 10px; padding: 16px 18px; }\u000a        .party-label { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #9ca3af; margin-bottom: 8px; }\u000a        .party-name { font-size: 14px; font-weight: 700; color: #111827; margin-bottom: 4px; }\u000a        .party-detail { font-size: 11px; color: #6b7280; line-height: 1.7; }\u000a\u000a        /* Items Table */\u000a        .section-title { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #9ca3af; margin-bottom: 10px; }\u000a        table { width: 100%; border-collapse: collapse; margin-bottom: 24px; }\u000a        thead tr { background: #1a1a2e; color: #fff; }\u000a        thead th { padding: 10px 14px; text-align: left; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; }\u000a        thead th:last-child { text-align: right; }\u000a        thead th.center { text-align: center; }\u000a        tbody tr { border-bottom: 1px solid #f3f4f6; }\u000a        tbody tr:nth-child(even) { background: #f9fafb; }\u000a        tbody td { padding: 10px 14px; font-size: 12px; color: #374151; }\u000a        tbody td.center { text-align: center; }\u000a        tbody td.right { text-align: right; font-weight: 600; }\u000a\u000a        /* Totals */\u000a        .totals-wrap { display: flex; justify-content: flex-end; margin-bottom: 32px; }\u000a        .totals-box { width: 280px; }\u000a        .totals-row { display: flex; justify-content: space-between; padding: 6px 0; font-size: 12px; border-bottom: 1px solid #f3f4f6; color: #6b7280; }\u000a        .totals-row.grand { font-size: 15px; font-weight: 800; color: #1a1a2e; border-bottom: none; border-top: 2px solid #1a1a2e; padding-top: 10px; margin-top: 4px; }\u000a        .totals-row.grand span:last-child { color: #f97316; }\u000a        .totals-row.discount span:last-child { color: #16a34a; }\u000a\u000a        /* Notes & Bank */\u000a        .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 32px; }\u000a        .info-box { background: #f9fafb; border-radius: 10px; padding: 16px 18px; }\u000a        .info-box-title { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #9ca3af; margin-bottom: 8px; }\u000a        .info-box p { font-size: 12px; color: #374151; line-height: 1.6; }\u000a        .info-box .bank-row { font-size: 11px; color: #6b7280; margin-bottom: 3px; }\u000a        .info-box .bank-row strong { color: #374151; }\u000a\u000a        /* Footer */\u000a        .doc-footer { text-align: center; border-top: 1px solid #f3f4f6; padding-top: 16px; font-size: 10px; color: #9ca3af; line-height: 1.8; }\u000a        .accent { color: #f97316; font-weight: 700; }\u000a\u000a        @media print {\u000a            body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\u000a            .page { padding: 20px; }\u000a        }\u000a    </style>\u000a</head>\u000a<body>\u000a<div class="page">\u000a\u000a    {{-- ═══ HEADER ═══ --}}\u000a    <div class="doc-header">\u000a        <div class="company-brand">\u000a            <div class="company-name">{{ $settings[''company_name''] ?? ''SolarTech ERP'' }}</div>\u000a            @if(!empty($settings[''company_tagline'']))\u000a            <div class="company-tagline">{{ $settings[''company_tagline''] }}</div>\u000a            @endif\u000a            <div class="company-meta">\u000a                @if(!empty($settings[''company_email''])){{ $settings[''company_email''] }}<br>@endif\u000a                @if(!empty($settings[''company_phone''])){{ $settings[''company_phone''] }}<br>@endif\u000a                @if(!empty($settings[''company_address''])){{ $settings[''company_address''] }}<br>@endif\u000a                @if(!empty($settings[''gst_number'']))<strong>GST:</strong> {{ $settings[''gst_number''] }}@endif\u000a            </div>\u000a        </div>\u000a        <div class="doc-badge">\u000a            <div class="doc-type">Sales Order</div>\u000a            <div class="doc-number">{{ $order->order_number }}</div>\u000a            <div class="doc-date">Date: {{ $order->created_at->format(''d M Y'') }}</div>\u000a            <div>\u000a                @php\u000a                    $sc = [''confirmed''=>''confirmed'',''processing''=>''processing'',''dispatched''=>''dispatched'',''completed''=>''completed'',''cancelled''=>''cancelled''];\u000a                    $pc = [''pending''=>''pay-pending'',''partial''=>''pay-partial'',''paid''=>''pay-paid''];\u000a                @endphp\u000a                <span class="status-banner status-{{ $sc[$order->status] ?? ''confirmed'' }}">{{ ucfirst($order->status) }}</span>\u000a                <span class="status-banner {{ $pc[$order->payment_status] ?? ''pay-pending'' }}">{{ ucfirst($order->payment_status) }}</span>\u000a            </div>\u000a        </div>\u000a    </div>\u000a\u000a    {{-- ═══ PARTIES ═══ --}}\u000a    <div class="parties">\u000a        <div class="party-card">\u000a            <div class="party-label">Bill To</div>\u000a            <div class="party-name">{{ $order->customer_name }}</div>\u000a            <div class="party-detail">\u000a                {{ $order->customer_email }}<br>\u000a                {{ $order->customer_phone }}<br>\u000a                {{ $order->customer_address }}\u000a            </div>\u000a        </div>\u000a        <div class="party-card">\u000a            <div class="party-label">From</div>\u000a            <div class="party-name">{{ $settings[''company_name''] ?? ''SolarTech ERP'' }}</div>\u000a            <div class="party-detail">\u000a                @if(!empty($settings[''company_email''])){{ $settings[''company_email''] }}<br>@endif\u000a                @if(!empty($settings[''company_phone''])){{ $settings[''company_phone''] }}<br>@endif\u000a                @if(!empty($settings[''gst_number'']))GST: {{ $settings[''gst_number''] }}<br>@endif\u000a                @if(!empty($settings[''pan_number'']))PAN: {{ $settings[''pan_number''] }}@endif\u000a            </div>\u000a        </div>\u000a    </div>\u000a\u000a    {{-- ═══ ITEMS ═══ --}}\u000a    <div class="section-title">Order Items</div>\u000a    <table>\u000a        <thead>\u000a            <tr>\u000a                <th style="width:40px;">#</th>\u000a                <th>Description</th>\u000a                <th class="center" style="width:70px;">Qty</th>\u000a                <th style="width:120px; text-align:right;">Unit Price</th>\u000a                <th style="width:120px; text-align:right;">Total</th>\u000a            </tr>\u000a        </thead>\u000a        <tbody>\u000a            @foreach($order->items as $i => $item)\u000a            <tr>\u000a                <td>{{ $i + 1 }}</td>\u000a                <td>{{ $item->description }}</td>\u000a                <td class="center">{{ $item->quantity }}</td>\u000a                <td class="right">₹{{ number_format($item->unit_price, 2) }}</td>\u000a                <td class="right">₹{{ number_format($item->total_price, 2) }}</td>\u000a            </tr>\u000a            @endforeach\u000a        </tbody>\u000a    </table>\u000a\u000a    {{-- ═══ TOTALS ═══ --}}\u000a    <div class="totals-wrap">\u000a        <div class="totals-box">\u000a            <div class="totals-row">\u000a                <span>Subtotal</span>\u000a                <span>₹{{ number_format($order->total_amount, 2) }}</span>\u000a            </div>\u000a            @if($order->tax_amount > 0)\u000a            <div class="totals-row">\u000a                <span>Tax</span>\u000a                <span>+₹{{ number_format($order->tax_amount, 2) }}</span>\u000a            </div>\u000a            @endif\u000a            @if($order->discount_amount > 0)\u000a            <div class="totals-row discount">\u000a                <span>Discount</span>\u000a                <span>-₹{{ number_format($order->discount_amount, 2) }}</span>\u000a            </div>\u000a            @endif\u000a            <div class="totals-row grand">\u000a                <span>Grand Total</span>\u000a                <span>₹{{ number_format($order->final_amount, 2) }}</span>\u000a            </div>\u000a        </div>\u000a    </div>\u000a\u000a    {{-- ═══ NOTES + BANK ═══ --}}\u000a    <div class="info-grid">\u000a        @if($order->notes)\u000a        <div class="info-box">\u000a            <div class="info-box-title">Notes</div>\u000a            <p>{{ $order->notes }}</p>\u000a        </div>\u000a        @endif\u000a        @if(!empty($settings[''bank_name'']))\u000a        <div class="info-box">\u000a            <div class="info-box-title">Bank Details</div>\u000a            <div class="bank-row"><strong>Bank:</strong> {{ $settings[''bank_name''] }}</div>\u000a            <div class="bank-row"><strong>A/C Name:</strong> {{ $settings[''bank_account_name''] ?? '''' }}</div>\u000a            <div class="bank-row"><strong>A/C No:</strong> {{ $settings[''bank_account_number''] ?? '''' }}</div>\u000a            <div class="bank-row"><strong>IFSC:</strong> {{ $settings[''bank_ifsc''] ?? '''' }}</div>\u000a            @if(!empty($settings[''upi_id'']))\u000a            <div class="bank-row"><strong>UPI:</strong> {{ $settings[''upi_id''] }}</div>\u000a            @endif\u000a        </div>\u000a        @endif\u000a    </div>\u000a\u000a    {{-- ═══ FOOTER ═══ --}}\u000a    <div class="doc-footer">\u000a        @if(!empty($settings[''invoice_footer'']))\u000a            {{ $settings[''invoice_footer''] }}<br>\u000a        @else\u000a            Thank you for your business. This is a computer-generated document and does not require a signature.<br>\u000a        @endif\u000a        <span class="accent">{{ $settings[''company_name''] ?? ''SolarTech ERP'' }}</span>\u000a        @if(!empty($settings[''company_website''])) · {{ $settings[''company_website''] }}@endif\u000a    </div>\u000a\u000a</div>\u000a</body>\u000a</html>\u000a'),1,1,'A4','portrait','2026-03-19 10:41:28','2026-03-19 10:41:28');
INSERT INTO print_formats VALUES(3,'Default Purchase Order','purchase_order',NULL,NULL,unistr('<!DOCTYPE html>\u000a<html lang="en">\u000a<head>\u000a    <meta charset="UTF-8">\u000a    <title>Purchase Order — {{ $order->po_number }}</title>\u000a    <style>\u000a        * { margin: 0; padding: 0; box-sizing: border-box; }\u000a        body { font-family: ''Segoe UI'', Arial, sans-serif; font-size: 13px; color: #1a1a2e; background: #fff; }\u000a        .page { max-width: 820px; margin: 0 auto; padding: 40px; }\u000a\u000a        .doc-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 36px; padding-bottom: 24px; border-bottom: 3px solid #8b5cf6; }\u000a        .company-name { font-size: 22px; font-weight: 800; color: #1a1a2e; }\u000a        .company-meta { margin-top: 10px; font-size: 11px; color: #6b7280; line-height: 1.7; }\u000a        .doc-badge { text-align: right; }\u000a        .doc-type { font-size: 28px; font-weight: 900; color: #8b5cf6; letter-spacing: -1px; text-transform: uppercase; }\u000a        .doc-number { font-size: 13px; font-weight: 600; color: #374151; margin-top: 4px; }\u000a        .doc-date { font-size: 11px; color: #9ca3af; margin-top: 2px; }\u000a\u000a        .status-pill { display: inline-flex; align-items: center; padding: 3px 10px; border-radius: 20px; font-size: 10px; font-weight: 700; text-transform: uppercase; margin-top: 6px; }\u000a        .s-pending   { background: #fef9c3; color: #a16207; }\u000a        .s-approved  { background: #dcfce7; color: #15803d; }\u000a        .s-ordered   { background: #dbeafe; color: #1d4ed8; }\u000a        .s-received  { background: #ede9fe; color: #7c3aed; }\u000a        .s-cancelled { background: #fee2e2; color: #dc2626; }\u000a\u000a        .parties { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 32px; }\u000a        .party-card { background: #f9fafb; border-radius: 10px; padding: 16px 18px; }\u000a        .party-label { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #9ca3af; margin-bottom: 8px; }\u000a        .party-name { font-size: 14px; font-weight: 700; color: #111827; margin-bottom: 4px; }\u000a        .party-detail { font-size: 11px; color: #6b7280; line-height: 1.7; }\u000a\u000a        .section-title { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #9ca3af; margin-bottom: 10px; }\u000a        table { width: 100%; border-collapse: collapse; margin-bottom: 24px; }\u000a        thead tr { background: #1a1a2e; color: #fff; }\u000a        thead th { padding: 10px 14px; text-align: left; font-size: 11px; font-weight: 600; text-transform: uppercase; }\u000a        thead th.right { text-align: right; }\u000a        thead th.center { text-align: center; }\u000a        tbody tr { border-bottom: 1px solid #f3f4f6; }\u000a        tbody tr:nth-child(even) { background: #f9fafb; }\u000a        tbody td { padding: 10px 14px; font-size: 12px; color: #374151; }\u000a        tbody td.center { text-align: center; }\u000a        tbody td.right { text-align: right; font-weight: 600; }\u000a\u000a        .totals-wrap { display: flex; justify-content: flex-end; margin-bottom: 32px; }\u000a        .totals-box { width: 280px; }\u000a        .totals-row { display: flex; justify-content: space-between; padding: 6px 0; font-size: 12px; border-bottom: 1px solid #f3f4f6; color: #6b7280; }\u000a        .totals-row.grand { font-size: 15px; font-weight: 800; color: #1a1a2e; border-bottom: none; border-top: 2px solid #1a1a2e; padding-top: 10px; margin-top: 4px; }\u000a        .totals-row.grand span:last-child { color: #8b5cf6; }\u000a\u000a        .info-box { background: #f9fafb; border-radius: 10px; padding: 16px 18px; margin-bottom: 24px; }\u000a        .info-box-title { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #9ca3af; margin-bottom: 8px; }\u000a        .info-box p { font-size: 12px; color: #374151; line-height: 1.6; }\u000a\u000a        .doc-footer { text-align: center; border-top: 1px solid #f3f4f6; padding-top: 16px; font-size: 10px; color: #9ca3af; line-height: 1.8; }\u000a        .accent { color: #8b5cf6; font-weight: 700; }\u000a\u000a        @media print {\u000a            body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\u000a            .page { padding: 20px; }\u000a        }\u000a    </style>\u000a</head>\u000a<body>\u000a<div class="page">\u000a\u000a    <div class="doc-header">\u000a        <div>\u000a            <div class="company-name">{{ $settings[''company_name''] ?? ''SolarTech ERP'' }}</div>\u000a            <div class="company-meta">\u000a                @if(!empty($settings[''company_email''])){{ $settings[''company_email''] }}<br>@endif\u000a                @if(!empty($settings[''company_phone''])){{ $settings[''company_phone''] }}<br>@endif\u000a                @if(!empty($settings[''company_address''])){{ $settings[''company_address''] }}<br>@endif\u000a                @if(!empty($settings[''gst_number'']))<strong>GST:</strong> {{ $settings[''gst_number''] }}@endif\u000a            </div>\u000a        </div>\u000a        <div class="doc-badge">\u000a            <div class="doc-type">Purchase Order</div>\u000a            <div class="doc-number">{{ $order->po_number }}</div>\u000a            <div class="doc-date">Date: {{ $order->created_at->format(''d M Y'') }}</div>\u000a            @if($order->expected_delivery)\u000a            <div style="font-size:11px;color:#6b7280;margin-top:2px;">Expected: {{ \\Carbon\\Carbon::parse($order->expected_delivery)->format(''d M Y'') }}</div>\u000a            @endif\u000a            <span class="status-pill s-{{ $order->status }}">{{ ucfirst($order->status) }}</span>\u000a        </div>\u000a    </div>\u000a\u000a    <div class="parties">\u000a        <div class="party-card">\u000a            <div class="party-label">Supplier</div>\u000a            <div class="party-name">{{ $order->supplier_name }}</div>\u000a            <div class="party-detail">\u000a                @if($order->supplier_email){{ $order->supplier_email }}<br>@endif\u000a                @if($order->supplier_phone){{ $order->supplier_phone }}<br>@endif\u000a                @if($order->supplier_address){{ $order->supplier_address }}@endif\u000a            </div>\u000a        </div>\u000a        <div class="party-card">\u000a            <div class="party-label">Deliver To</div>\u000a            <div class="party-name">{{ $settings[''company_name''] ?? ''SolarTech ERP'' }}</div>\u000a            <div class="party-detail">\u000a                @if(!empty($settings[''company_address''])){{ $settings[''company_address''] }}<br>@endif\u000a                @if(!empty($settings[''company_phone''])){{ $settings[''company_phone''] }}@endif\u000a            </div>\u000a        </div>\u000a    </div>\u000a\u000a    <div class="section-title">Purchase Items</div>\u000a    <table>\u000a        <thead>\u000a            <tr>\u000a                <th style="width:40px;">#</th>\u000a                <th>Description</th>\u000a                <th class="center" style="width:70px;">Qty</th>\u000a                <th class="right" style="width:120px;">Unit Price</th>\u000a                <th class="right" style="width:120px;">Total</th>\u000a            </tr>\u000a        </thead>\u000a        <tbody>\u000a            @foreach($order->items as $i => $item)\u000a            <tr>\u000a                <td>{{ $i + 1 }}</td>\u000a                <td>{{ $item->description }}</td>\u000a                <td class="center">{{ $item->quantity }}</td>\u000a                <td class="right">₹{{ number_format($item->unit_price, 2) }}</td>\u000a                <td class="right">₹{{ number_format($item->total_price, 2) }}</td>\u000a            </tr>\u000a            @endforeach\u000a        </tbody>\u000a    </table>\u000a\u000a    <div class="totals-wrap">\u000a        <div class="totals-box">\u000a            <div class="totals-row"><span>Subtotal</span><span>₹{{ number_format($order->total_amount, 2) }}</span></div>\u000a            @if($order->tax_amount > 0)\u000a            <div class="totals-row"><span>Tax</span><span>+₹{{ number_format($order->tax_amount, 2) }}</span></div>\u000a            @endif\u000a            <div class="totals-row grand"><span>Grand Total</span><span>₹{{ number_format($order->final_amount, 2) }}</span></div>\u000a        </div>\u000a    </div>\u000a\u000a    @if($order->notes)\u000a    <div class="info-box">\u000a        <div class="info-box-title">Notes / Instructions</div>\u000a        <p>{{ $order->notes }}</p>\u000a    </div>\u000a    @endif\u000a\u000a    <div class="doc-footer">\u000a        This is an official Purchase Order. Please quote the PO number in all correspondence.<br>\u000a        <span class="accent">{{ $settings[''company_name''] ?? ''SolarTech ERP'' }}</span>\u000a        @if(!empty($settings[''company_website''])) · {{ $settings[''company_website''] }}@endif\u000a    </div>\u000a\u000a</div>\u000a</body>\u000a</html>\u000a'),1,1,'A4','portrait','2026-03-19 10:41:28','2026-03-19 10:41:28');
INSERT INTO print_formats VALUES(4,'Custom Quotation','quotation',NULL,NULL,unistr('<style>\u000a    .quotation-replica {\u000a        color: #122844;\u000a        font-family: "Arial", sans-serif;\u000a    }\u000a\u000a    .quotation-replica * {\u000a        box-sizing: border-box;\u000a    }\u000a\u000a    .quotation-replica .page {\u000a        position: relative;\u000a        page-break-after: always;\u000a        padding: 18px 22px 22px;\u000a        background: #ffffff;\u000a        overflow: hidden;\u000a    }\u000a\u000a    .quotation-replica .page:last-child {\u000a        page-break-after: auto;\u000a    }\u000a\u000a    .quotation-replica .cover-page {\u000a        padding-top: 34px;\u000a    }\u000a\u000a    .quotation-replica .meta-top {\u000a        display: table;\u000a        width: 100%;\u000a        margin-bottom: 14px;\u000a    }\u000a\u000a    .quotation-replica .meta-top .meta-left,\u000a    .quotation-replica .meta-top .meta-right {\u000a        display: table-cell;\u000a        vertical-align: top;\u000a    }\u000a\u000a    .quotation-replica .meta-top .meta-right {\u000a        text-align: right;\u000a        font-size: 14px;\u000a        font-weight: 700;\u000a        line-height: 1.65;\u000a        color: #4b5563;\u000a    }\u000a\u000a    .quotation-replica .logo {\u000a        width: 138px;\u000a        max-height: 92px;\u000a        object-fit: contain;\u000a    }\u000a\u000a    .quotation-replica .watermark {\u000a        position: absolute;\u000a        top: 50%;\u000a        left: 50%;\u000a        width: 300px;\u000a        max-width: 56%;\u000a        transform: translate(-50%, -50%);\u000a        opacity: 0.2;\u000a        z-index: 0;\u000a        pointer-events: none;\u000a    }\u000a\u000a    .quotation-replica .cover-title {\u000a        position: relative;\u000a        z-index: 1;\u000a        margin-top: 2px;\u000a        text-align: center;\u000a        font-size: 46px;\u000a        line-height: 1;\u000a        font-weight: 8