PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "admin_users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "password" varchar not null, "role" varchar not null default 'user', "role_id" integer, "permissions" text, "is_active" tinyint(1) not null default '1', "remember_token" varchar, "created_at" datetime, "updated_at" datetime, foreign key("role_id") references "roles"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" varchar, "permissions" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "customers" ("id" integer primary key autoincrement not null, "customer_code" varchar not null, "name" varchar not null, "email" varchar not null, "phone" varchar not null, "address" text not null, "city" varchar not null, "state" varchar not null, "pincode" varchar, "customer_type" varchar check ("customer_type" in ('residential', 'commercial', 'industrial')) not null default 'residential', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "packages" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "system_size_kw" numeric not null, "price" numeric not null, "suitable_for" varchar check ("suitable_for" in ('residential', 'commercial', 'industrial')) not null default 'residential', "includes" text, "items" text, "warranty_years" integer, "is_active" tinyint(1) not null default '1', "is_featured" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "leads" ("id" integer primary key autoincrement not null, "lead_number" varchar not null, "customer_id" integer, "package_id" integer, "name" varchar not null, "email" varchar not null, "phone" varchar not null, "address" text not null, "lead_source" varchar check ("lead_source" in ('website', 'referral', 'cold_call', 'social_media', 'exhibition', 'other')) not null default 'website', "estimated_value" numeric, "roof_type" varchar, "system_size" varchar, "notes" text, "status" varchar check ("status" in ('new', 'contacted', 'follow_up', 'mature', 'converted', 'lost')) not null default 'new', "assigned_to" integer, "created_at" datetime, "updated_at" datetime, "k_number" varchar, "monthly_electricity_bill" numeric, "required_load_kw" varchar, "sanctioned_load" varchar, "meter_type" varchar, "property_type" varchar, "roof_area_sqft" varchar, "has_subsidy" tinyint(1) not null default '0', "follow_up_notes" text, "next_follow_up_date" date, "sms_sent" tinyint(1) not null default '0', "email_sent" tinyint(1) not null default '0', "last_contacted_at" datetime, "subsidy_status" varchar, "subsidy_amount" float, "subsidy_ref_number" varchar, "subsidy_notes" text, "latitude" numeric, "longitude" numeric, "requires_loan" tinyint(1) not null default '0', foreign key("customer_id") references "customers"("id") on delete set null, foreign key("package_id") references "packages"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "quotations" ("id" integer primary key autoincrement not null, "quotation_number" varchar not null, "lead_id" integer, "customer_id" integer, "package_id" integer, "customer_name" varchar not null, "customer_email" varchar not null, "customer_phone" varchar not null, "customer_address" text not null, "total_amount" numeric not null default '0', "tax_amount" numeric not null default '0', "discount_amount" numeric not null default '0', "final_amount" numeric not null default '0', "status" varchar check ("status" in ('pending', 'sent', 'approved', 'rejected', 'expired')) not null default 'pending', "valid_until" date, "sent_at" datetime, "notes" text, "created_at" datetime, "updated_at" datetime, "bom_items" text, foreign key("lead_id") references "leads"("id") on delete set null, foreign key("customer_id") references "customers"("id") on delete set null, foreign key("package_id") references "packages"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "quotation_items" ("id" integer primary key autoincrement not null, "quotation_id" integer not null, "product_id" integer, "description" varchar not null, "quantity" numeric not null, "unit_price" numeric not null, "total_price" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("quotation_id") references "quotations"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sales_order_items" ("id" integer primary key autoincrement not null, "sales_order_id" integer not null, "product_id" integer, "description" varchar not null, "quantity" numeric not null, "unit_price" numeric not null, "total_price" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("sales_order_id") references "sales_orders"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "purchase_orders" ("id" integer primary key autoincrement not null, "po_number" varchar not null, "supplier_name" varchar not null, "supplier_email" varchar, "supplier_phone" varchar, "supplier_address" text, "total_amount" numeric not null default '0', "tax_amount" numeric not null default '0', "final_amount" numeric not null default '0', "status" varchar check ("status" in ('pending', 'approved', 'ordered', 'received', 'cancelled')) not null default 'pending', "expected_delivery" date, "received_date" date, "notes" text, "created_at" datetime, "updated_at" datetime, "invoice_attachments" text);
CREATE TABLE IF NOT EXISTS "purchase_order_items" ("id" integer primary key autoincrement not null, "purchase_order_id" integer not null, "product_id" integer, "description" varchar not null, "quantity" numeric not null, "unit_price" numeric not null, "total_price" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("purchase_order_id") references "purchase_orders"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "inventories" ("id" integer primary key autoincrement not null, "product_id" integer not null, "quantity" integer not null default '0', "min_quantity" integer not null default '5', "location" varchar, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "inventory_adjustments" ("id" integer primary key autoincrement not null, "inventory_id" integer not null, "product_id" integer not null, "adjustment_type" varchar check ("adjustment_type" in ('add', 'remove', 'set')) not null, "quantity_before" integer not null, "quantity_adjusted" integer not null, "quantity_after" integer not null, "reason" varchar not null, "adjusted_by" varchar, "created_at" datetime, "updated_at" datetime, foreign key("inventory_id") references "inventories"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "service_requests" ("id" integer primary key autoincrement not null, "ticket_number" varchar not null, "customer_id" integer not null, "installation_id" integer, "service_type" varchar check ("service_type" in ('maintenance', 'repair', 'inspection', 'cleaning', 'warranty')) not null, "priority" varchar check ("priority" in ('low', 'medium', 'high', 'urgent')) not null default 'medium', "status" varchar check ("status" in ('open', 'in_progress', 'resolved', 'closed')) not null default 'open', "description" text not null, "scheduled_date" date, "assigned_to" varchar, "resolution_notes" text, "service_cost" numeric, "resolved_at" datetime, "created_at" datetime, "updated_at" datetime, "assigned_employee_id" integer, foreign key("customer_id") references "customers"("id") on delete cascade, foreign key("installation_id") references "installations"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "salary_records" ("id" integer primary key autoincrement not null, "employee_id" integer not null, "month" integer not null, "year" integer not null, "basic_salary" numeric not null, "allowances" numeric not null default '0', "deductions" numeric not null default '0', "net_salary" numeric not null, "payment_date" date not null, "payment_mode" varchar check ("payment_mode" in ('cash', 'bank_transfer', 'cheque')) not null, "status" varchar check ("status" in ('paid', 'pending')) not null default 'paid', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("employee_id") references "employees"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "notifications" ("id" integer primary key autoincrement not null, "title" varchar not null, "message" text not null, "type" varchar not null default 'general', "related_id" integer, "related_type" varchar, "is_read" tinyint(1) not null default '0', "read_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "group" varchar not null default 'general', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "email_templates" ("id" integer primary key autoincrement not null, "name" varchar not null, "type" varchar not null, "subject" varchar not null, "body" text not null, "variables" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "print_formats" ("id" integer primary key autoincrement not null, "name" varchar not null, "document_type" varchar check ("document_type" in ('quotation', 'sales_order', 'purchase_order', 'invoice', 'salary_slip')) not null, "header_html" text, "footer_html" text, "body_template" text not null, "is_default" tinyint(1) not null default '0', "is_active" tinyint(1) not null default '1', "paper_size" varchar check ("paper_size" in ('A4', 'A5', 'Letter')) not null default 'A4', "orientation" varchar check ("orientation" in ('portrait', 'landscape')) not null default 'portrait', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "product_categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "icon" varchar default 'fas fa-solar-panel', "image" varchar, "color" varchar default 'orange', "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "products" ("id" integer primary key autoincrement not null, "name" varchar not null, "sku" varchar not null, "category" varchar not null, "brand" varchar, "description" text, "specifications" text, "purchase_price" numeric not null, "selling_price" numeric not null, "unit" varchar not null default ('piece'), "warranty_months" integer, "image" varchar, "is_active" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "category_id" integer, foreign key("category_id") references "product_categories"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sms_configurations" ("id" integer primary key autoincrement not null, "provider" varchar not null default 'twilio', "account_sid" varchar, "auth_token" varchar, "from_number" varchar, "api_key" varchar, "sender_id" varchar, "region" varchar default 'IN', "is_active" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sms_templates" ("id" integer primary key autoincrement not null, "name" varchar not null, "type" varchar not null, "message" text not null, "variables_help" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sms_logs" ("id" integer primary key autoincrement not null, "to_number" varchar not null, "to_name" varchar, "message" text not null, "type" varchar, "related_type" varchar, "related_id" integer, "status" varchar not null default 'pending', "provider_message_id" varchar, "error_message" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "message_logs" ("id" integer primary key autoincrement not null, "channel" varchar not null, "to" varchar not null, "to_name" varchar, "subject" varchar, "body" text not null, "status" varchar not null default 'sent', "related_type" varchar, "related_id" integer, "sent_by" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "teams" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, "installation_rate" numeric not null default '0', "leader_id" integer, "site_visit_rate" numeric not null default '0', "service_rate" numeric not null default '0');
CREATE TABLE IF NOT EXISTS "blogs" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "short_description" varchar, "content" text not null, "image" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "overview_url" varchar);
CREATE TABLE IF NOT EXISTS "sales_invoice_items" ("id" integer primary key autoincrement not null, "sales_invoice_id" integer not null, "product_id" integer, "product_name" varchar not null, "quantity" integer not null, "unit_price" numeric not null, "tax_rate" numeric not null default '0', "tax_amount" numeric not null default '0', "total" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("sales_invoice_id") references "sales_invoices"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sales_invoices" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "sales_order_id" integer, "invoice_number" varchar not null, "invoice_date" date not null, "due_date" date, "sub_total" numeric not null default '0', "tax_amount" numeric not null default '0', "discount_amount" numeric not null default '0', "grand_total" numeric not null default '0', "paid_amount" numeric not null default '0', "balance_due" numeric not null default '0', "status" varchar check ("status" in ('unpaid', 'partially_paid', 'paid', 'cancelled')) not null default 'unpaid', "notes" text, "created_at" datetime, "updated_at" datetime, "bom_items" text, foreign key("customer_id") references "customers"("id") on delete cascade, foreign key("sales_order_id") references "sales_orders"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "payment_receipts" ("id" integer primary key autoincrement not null, "sales_invoice_id" integer not null, "receipt_number" varchar not null, "payment_date" date not null, "amount" numeric not null, "payment_method" varchar not null, "reference_number" varchar, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("sales_invoice_id") references "sales_invoices"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sales_orders" ("id" integer primary key autoincrement not null, "order_number" varchar not null, "quotation_id" integer, "customer_id" integer, "customer_name" varchar not null, "customer_email" varchar not null, "customer_phone" varchar not null, "customer_address" text not null, "total_amount" numeric not null default ('0'), "tax_amount" numeric not null default ('0'), "discount_amount" numeric not null default ('0'), "final_amount" numeric not null default ('0'), "status" varchar not null default ('confirmed'), "payment_status" varchar not null default ('pending'), "notes" text, "created_at" datetime, "updated_at" datetime, "advance_payment" numeric not null default ('0'), "site_visit_id" integer, "bom_items" text, foreign key("customer_id") references customers("id") on delete set null on update no action, foreign key("quotation_id") references quotations("id") on delete set null on update no action, foreign key("site_visit_id") references "site_visits"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "installations" ("id" integer primary key autoincrement not null, "installation_number" varchar not null, "customer_id" integer not null, "sales_order_id" integer, "scheduled_date" date not null, "completion_date" date, "system_size_kw" numeric not null, "installation_address" text not null, "roof_type" varchar not null, "assigned_team" varchar, "status" varchar not null default ('scheduled'), "notes" text, "completion_photos" text, "created_at" datetime, "updated_at" datetime, "proof_photos" text, "proof_before_photo" varchar, "proof_during_photo" varchar, "proof_after_photo" varchar, "proof_meter_photo" varchar, "proof_panel_photo" varchar, "proof_inverter_photo" varchar, "proof_submitted" tinyint(1) not null default ('0'), "proof_submitted_at" datetime, "technician_remarks" text, "auto_service_created" tinyint(1) not null default ('0'), "installation_checklist" text, "sales_invoice_id" integer, "panel_serial_details" text, "inverter_serial_number" varchar, "net_meter_serial_number" varchar, "initial_meter_reading" varchar, "structure_panel_photo" varchar, "ground_setup_photo" varchar, "roof_setup_photo" varchar, "panel_angle_photo" varchar, "site_location_photo" varchar, "wiring_photo" varchar, "meter_setup_photo" varchar, "el_test_report" varchar, "commissioning_report" varchar, "latitude" numeric, "longitude" numeric, "inverter_serial_details" text, "assigned_team_id" integer, foreign key("sales_order_id") references sales_orders("id") on delete set null on update no action, foreign key("customer_id") references customers("id") on delete cascade on update no action, foreign key("sales_invoice_id") references "sales_invoices"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "expenses" ("id" integer primary key autoincrement not null, "title" varchar not null, "category" varchar, "amount" numeric not null, "expense_date" date not null, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "customer_loans" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "bank_name" varchar, "loan_amount" numeric, "account_number" varchar, "ifsc_code" varchar, "loan_status" varchar not null default 'pending', "loan_notes" text, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_subsidies" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "subsidy_status" varchar not null default 'not_applied', "subsidy_amount" numeric, "reference_number" varchar, "portal_application_no" varchar, "subsidy_notes" text, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_discoms" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "discom_name" varchar, "k_number" varchar, "sanctioned_load" varchar, "required_load_kw" varchar, "meter_type" varchar, "property_type" varchar, "roof_area_sqft" varchar, "notes" text, "created_at" datetime, "updated_at" datetime, "application_data" text, "workflow_status" varchar not null default 'not_started', "application_date" date, "submission_number" varchar, "discom_portal_username" varchar, "discom_portal_password" varchar, "meter_number" varchar, "application_number" varchar, "dcr_report_path" varchar, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "employees" ("id" integer primary key autoincrement not null, "employee_code" varchar not null, "name" varchar not null, "email" varchar not null, "phone" varchar not null, "department" varchar not null, "designation" varchar not null, "basic_salary" numeric, "joining_date" date not null, "address" text, "is_active" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "employment_type" varchar check ("employment_type" in ('permanent', 'contract', 'daily_wage')) not null default 'permanent', "contract_start_date" date, "contract_end_date" date, "contract_amount" numeric, "daily_wage_rate" numeric, "installation_rate" numeric not null default '0', "site_visit_rate" numeric not null default '0', "service_rate" numeric not null default '0');
CREATE TABLE IF NOT EXISTS "daily_wage_records" ("id" integer primary key autoincrement not null, "employee_id" integer not null, "work_date" date not null, "hours_worked" numeric not null default '8', "wage_rate" numeric not null, "total_amount" numeric not null, "work_description" varchar, "installation_id" integer, "site_visit_id" integer, "payment_status" varchar check ("payment_status" in ('pending', 'paid')) not null default 'pending', "payment_date" date, "payment_mode" varchar check ("payment_mode" in ('cash', 'bank_transfer', 'cheque')), "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("employee_id") references "employees"("id") on delete cascade, foreign key("installation_id") references "installations"("id") on delete set null, foreign key("site_visit_id") references "site_visits"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "site_visits" ("id" integer primary key autoincrement not null, "visit_number" varchar not null, "customer_id" integer, "lead_id" integer, "scheduled_at" datetime not null, "status" varchar not null default ('scheduled'), "discom_details" varchar, "has_new_connection" tinyint(1) not null default ('0'), "roof_details" text, "system_size_kw" float, "technical_notes" text, "assigned_to" varchar, "completed_at" datetime, "completion_notes" text, "created_at" datetime, "updated_at" datetime, "shadow_analysis" text, "wiring_length_estimate" varchar, "ac_dc_location" text, "is_approved" tinyint(1) not null default ('0'), "approved_by" varchar, "approved_at" datetime, "latitude" numeric, "longitude" numeric, "created_by" integer, "completed_by" integer, "site_photos" text, "started_at" datetime, "assigned_employee_id" integer, "team_id" integer, foreign key("lead_id") references leads("id") on delete cascade on update no action, foreign key("customer_id") references customers("id") on delete cascade on update no action, foreign key("created_by") references "admin_users"("id") on delete set null, foreign key("completed_by") references "admin_users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "task_payments" ("id" integer primary key autoincrement not null, "employee_id" integer not null, "taskable_type" varchar not null, "taskable_id" integer not null, "amount" numeric not null, "status" varchar not null default 'pending', "payment_date" date, "payment_mode" varchar, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("employee_id") references "employees"("id") on delete cascade);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "admin_users_email_unique" on "admin_users" ("email");
CREATE UNIQUE INDEX "roles_name_unique" on "roles" ("name");
CREATE UNIQUE INDEX "customers_customer_code_unique" on "customers" ("customer_code");
CREATE UNIQUE INDEX "customers_email_unique" on "customers" ("email");
CREATE UNIQUE INDEX "leads_lead_number_unique" on "leads" ("lead_number");
CREATE UNIQUE INDEX "quotations_quotation_number_unique" on "quotations" ("quotation_number");
CREATE UNIQUE INDEX "purchase_orders_po_number_unique" on "purchase_orders" ("po_number");
CREATE UNIQUE INDEX "service_requests_ticket_number_unique" on "service_requests" ("ticket_number");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE UNIQUE INDEX "product_categories_slug_unique" on "product_categories" ("slug");
CREATE UNIQUE INDEX "products_sku_unique" on "products" ("sku");
CREATE UNIQUE INDEX "blogs_slug_unique" on "blogs" ("slug");
CREATE UNIQUE INDEX "sales_invoices_invoice_number_unique" on "sales_invoices" ("invoice_number");
CREATE UNIQUE INDEX "payment_receipts_receipt_number_unique" on "payment_receipts" ("receipt_number");
CREATE UNIQUE INDEX "sales_orders_order_number_unique" on "sales_orders" ("order_number");
CREATE UNIQUE INDEX "installations_installation_number_unique" on "installations" ("installation_number");
CREATE UNIQUE INDEX "employees_email_unique" on "employees" ("email");
CREATE UNIQUE INDEX "employees_employee_code_unique" on "employees" ("employee_code");
CREATE INDEX "daily_wage_records_employee_id_work_date_index" on "daily_wage_records" ("employee_id", "work_date");
CREATE UNIQUE INDEX "site_visits_visit_number_unique" on "site_visits" ("visit_number");
CREATE INDEX "task_payments_taskable_type_taskable_id_index" on "task_payments" ("taskable_type", "taskable_id");
PRAGMA writable_schema=OFF;
COMMIT;
